// Parity for the Rust narrow phase (plan-rust.md R2): sweeps, closest points and rayAabb must give the very bits of
// narrow.ts, 10,000 seeded cases each. The module is instantiated from the generated bytes directly, so this test
// does not depend on the kernel loader or the physics world.
import { beforeAll, describe, expect, it } from 'vitest';
import { KERNEL_BASE64 } from '../kernel/wasm.ts';
import { B, beginSweep, C, closestOn, rayAabb, sweepShape } from './narrow.ts';
import { K, Shape } from './shape.ts';
import type { ShapeDesc } from './types.ts';

// Header slots (lib.rs mod h) and the shape table's strides and fields (shapes.rs).
const H_SF = 1, H_SI = 2, H_RES = 4, H_UPF = 8, H_UPI = 9, H_UPH = 10;
const SF = 48, SI = 12;
const F = { CX: 0, AX: 3, BX: 6, R: 9, HX: 10, U: 13, PLANE_Y: 22 };
const I = { FLAGS: 3, DATA: 6 };
const F_AA = 8;

interface Exports {
  memory: WebAssembly.Memory;
  hk_hdr(): number;
  hk_shape_new(kind: number): number;
  hk_mesh_data(tris: number, nodes: number): number;
  hk_hf_data(columns: number, rows: number): number;
  hk_t_sweep(id: number, ox: number, oy: number, oz: number, dx: number, dy: number, dz: number, r: number): void;
  hk_t_closest(id: number, px: number, py: number, pz: number): number;
  hk_t_ray_aabb(...a: number[]): number;
}

let ex!: Exports;
let hdr!: number;

beforeAll(() => {
  const bytes = Uint8Array.from(atob(KERNEL_BASE64), (c) => c.charCodeAt(0));
  ex = new WebAssembly.Instance(new WebAssembly.Module(bytes), {}).exports as unknown as Exports;
  hdr = ex.hk_hdr();
});

// Views are made fresh each time: any call may grow the memory and detach the old buffer.
const H = (): Int32Array => new Int32Array(ex.memory.buffer, hdr, 64);
const f64 = (byte: number, n: number): Float64Array => new Float64Array(ex.memory.buffer, byte, n);
const i32 = (byte: number, n: number): Int32Array => new Int32Array(ex.memory.buffer, byte, n);
const res = (): Float64Array => f64(H()[H_RES]!, 16);

function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}

/** Copies a TypeScript shape's pose and data into the kernel; returns its id. */
function load(s: Shape): number {
  const id = ex.hk_shape_new(s.kind);
  let data = -1;
  if (s.kind === K.mesh) {
    const m = s.mesh!;
    data = ex.hk_mesh_data(m.tris, m.nodes);
    const fb = f64(H()[H_UPF]!, m.tris * 12 + m.nodes * 6);
    fb.set(m.v.subarray(0, m.tris * 9), 0);
    fb.set(m.n.subarray(0, m.tris * 3), m.tris * 9);
    fb.set(m.bb.subarray(0, m.nodes * 6), m.tris * 12);
    const ib = i32(H()[H_UPI]!, m.nodes * 4);
    ib.set(m.left.subarray(0, m.nodes), 0);
    ib.set(m.right.subarray(0, m.nodes), m.nodes);
    ib.set(m.first.subarray(0, m.nodes), 2 * m.nodes);
    ib.set(m.count.subarray(0, m.nodes), 3 * m.nodes);
  } else if (s.kind === K.heightfield) {
    const hf = s.hf!;
    data = ex.hk_hf_data(hf.columns, hf.rows);
    f64(H()[H_UPF]!, 5).set([hf.cell, hf.x0, hf.z0, hf.y0, hf.scale]);
    new Float32Array(ex.memory.buffer, H()[H_UPH]!, hf.columns * hf.rows).set(hf.h);
  }
  const sf = f64(H()[H_SF]! + id * SF * 8, SF);
  sf.set([s.cx, s.cy, s.cz, s.ax, s.ay, s.az, s.bx, s.by, s.bz, s.r, s.hx, s.hy, s.hz], 0);
  sf.set(s.u, F.U);
  sf[F.PLANE_Y] = s.planeY;
  const si = i32(H()[H_SI]! + id * SI * 4, SI);
  si[I.FLAGS] = 1 | 4 | (s.aa ? F_AA : 0);
  si[I.DATA] = data;
  return id;
}

const same = (a: number, b: number): boolean => Object.is(a, b);

function randQuat(R: () => number): { x: number; y: number; z: number; w: number } {
  const x = R() * 2 - 1, y = R() * 2 - 1, z = R() * 2 - 1, w = R() * 2 - 1;
  const l = Math.hypot(x, y, z, w) || 1;
  return { x: x / l, y: y / l, z: z / l, w: w / l };
}

/** A seeded shape of each kind; boxes are axis-aligned about half the time, the rest rotated. */
function makeShape(kind: number, R: () => number, n: number): Shape {
  const pos = { x: (R() * 2 - 1) * 8, y: (R() * 2 - 1) * 6, z: (R() * 2 - 1) * 8 };
  const q = R() < 0.5 ? undefined : randQuat(R);
  const opt = { position: pos, quaternion: q };
  const sz = () => 0.3 + R() * 3;
  switch (kind) {
    case K.sphere: return new Shape({ type: 'sphere', radius: sz(), center: [R() - 0.5, R() - 0.5, R() - 0.5] }, opt);
    case K.capsule: {
      const r = 0.2 + R() * 1.5;
      return new Shape({ type: 'capsule', radius: r, height: r * 2 + R() * 4 }, opt);
    }
    case K.box: {
      const aa = n % 2 === 0;
      return new Shape({ type: 'box', size: [sz() * 2, sz() * 2, sz() * 2] }, aa ? { position: pos } : { position: pos, quaternion: randQuat(R) });
    }
    case K.mesh: {
      // A bumpy sheet of triangles (some made degenerate), or a soup, big enough for a BVH several levels deep.
      const soup = n % 5 === 4;
      const pts: number[] = [];
      let idx: number[] | undefined;
      if (soup) {
        for (let t = 0; t < 150; t++) {
          const cx = (R() * 2 - 1) * 6, cy = (R() * 2 - 1) * 4, cz = (R() * 2 - 1) * 6;
          for (let v = 0; v < 3; v++) pts.push(cx + (R() - 0.5) * 3, cy + (R() - 0.5) * 3, cz + (R() - 0.5) * 3);
        }
      } else {
        const g = 10 + (n % 6);
        for (let j = 0; j < g; j++) for (let i = 0; i < g; i++) pts.push((i - g / 2) * 1.2, R() * 2.5, (j - g / 2) * 1.2);
        idx = [];
        for (let j = 0; j < g - 1; j++) {
          for (let i = 0; i < g - 1; i++) {
            const a = j * g + i, b = a + 1, c = a + g, d = c + 1;
            idx.push(a, c, b, b, c, d);
          }
        }
        if (n % 3 === 0) idx.push(0, 0, 1, 2, 2, 2);
      }
      return new Shape({ type: 'mesh', positions: pts, indices: idx }, opt);
    }
    case K.plane: return new Shape({ type: 'plane', height: (R() * 2 - 1) * 4 }, {});
    default: {
      const columns = 6 + Math.floor(R() * 14), rows = 6 + Math.floor(R() * 14);
      const heights: number[] = [];
      for (let i = 0; i < columns * rows; i++) heights.push(R() * 3);
      const cell = 0.4 + R() * 1.6;
      return new Shape({ type: 'heightfield', heights, columns, rows, cell, origin: [(R() - 0.5) * 8 - (columns * cell) / 2, (R() - 0.5) * 8 - (rows * cell) / 2], baseY: (R() - 0.5) * 3, scale: 0.3 + R() * 2 }, {});
    }
  }
}

const NAMES = ['sphere', 'capsule', 'box', 'mesh', 'plane', 'heightfield'];
const PER_KIND = 40;
const CASES = 250; // per shape: 40 * 250 = 10,000 a kind

/** A point in the shape's neighbourhood: inside its bounds, grown. The plane's bounds are huge, so it gets a fixed range. */
function nearPoint(s: Shape, R: () => number, grow: number): [number, number, number] {
  if (s.kind === K.plane) return [(R() * 2 - 1) * 15, s.planeY + (R() * 2 - 1) * 6, (R() * 2 - 1) * 15];
  const g = (lo: number, hi: number) => lo - grow + R() * (hi - lo + 2 * grow);
  return [g(s.minx, s.maxx), g(s.miny, s.maxy), g(s.minz, s.maxz)];
}

describe('narrow phase in Rust, bit for bit with narrow.ts', () => {
  for (let kind = 0; kind < 6; kind++) {
    it('sweeps against a ' + NAMES[kind] + ' (' + PER_KIND * CASES + ' cases)', () => {
      const R = rng(1000 + kind);
      // A shape that earlier hits come from: the sweep must not hand its win to the shape under test.
      const other = new Shape({ type: 'sphere', radius: 1 }, {});
      const otherId = load(other);
      let hits = 0, inside = 0, total = 0, zero = 0;
      for (let n = 0; n < PER_KIND; n++) {
        const s = makeShape(kind, R, n);
        const id = load(s);
        for (let c = 0; c < CASES; c++) {
          // Origin: inside the shape's bounds a third of the time, otherwise around it.
          const o = nearPoint(s, R, R() < 0.35 ? 0 : 4 + R() * 6);
          let d: [number, number, number];
          const pick = R();
          if (pick < 0.08) {
            // Axis-aligned directions reach the zero-component branches.
            const a = Math.floor(R() * 3), sg = R() < 0.5 ? -1 : 1;
            d = [a === 0 ? sg : 0, a === 1 ? sg : 0, a === 2 ? sg : 0];
          } else if (pick < 0.65) {
            const t = nearPoint(s, R, 0.5);
            d = [t[0] - o[0], t[1] - o[1], t[2] - o[2]];
          } else d = [R() * 2 - 1, R() * 2 - 1, R() * 2 - 1];
          const l = Math.hypot(d[0], d[1], d[2]) || 1;
          d = [d[0] / l, d[1] / l, d[2] / l];
          const r = R() < 0.45 ? 0 : 0.05 + R() * 1.5;
          const kr = R();
          const maxT = kr < 0.05 ? 0 : kr < 0.08 ? Infinity : 1 + R() * 40;

          // Both sides start from the same B: nothing found yet, or an earlier hit from another shape.
          beginSweep(maxT);
          B.nx = 0; B.ny = 0; B.nz = 0; // beginSweep leaves the normal as it was; the kernel's is seeded at zero
          const q = res();
          q[0] = maxT; q[1] = 0; q[2] = 0; q[3] = 0; q[4] = -1; q[5] = 0; q[6] = 0;
          if (R() < 0.4) {
            const t = R() < 0.1 ? 0 : R() * (Number.isFinite(maxT) ? maxT : 40);
            const nx = R(), ny = R(), nz = R(), ins = R() < 0.3, dep = R();
            B.t = t; B.nx = nx; B.ny = ny; B.nz = nz; B.shape = other; B.inside = ins; B.depth = dep;
            q[0] = t; q[1] = nx; q[2] = ny; q[3] = nz; q[4] = otherId; q[5] = ins ? 1 : 0; q[6] = dep;
          }
          sweepShape(s, o[0], o[1], o[2], d[0], d[1], d[2], r);
          ex.hk_t_sweep(id, o[0], o[1], o[2], d[0], d[1], d[2], r);
          const k = res();
          const sid = B.shape === s ? id : B.shape === other ? otherId : -1;
          const ok = same(k[0]!, B.t) && same(k[1]!, B.nx) && same(k[2]!, B.ny) && same(k[3]!, B.nz) && k[4] === sid &&
            k[5] === (B.inside ? 1 : 0) && same(k[6]!, B.depth);
          if (!ok) {
            throw new Error('sweep differs: ' + NAMES[kind] + ' ' + n + ' case ' + c + ' o=' + o + ' d=' + d + ' r=' + r + ' maxT=' + maxT +
              ' ts=' + [B.t, B.nx, B.ny, B.nz, sid, B.inside, B.depth] + ' rs=' + Array.from(k.subarray(0, 7)));
          }
          total++;
          if (B.shape === s) { hits++; if (B.inside) inside++; if (B.t === 0) zero++; }
        }
      }
      // A comparison of misses with misses proves little: a healthy share must be hits.
      if (process.env.NARROW_STATS) console.log(NAMES[kind], 'sweep hits', hits / total, 'inside', inside, 'zero', zero);
      expect(total).toBe(PER_KIND * CASES);
      expect(hits / total).toBeGreaterThan(0.15);
      expect(inside).toBeGreaterThan(50);
      void zero;
    });

    it('closest points on a ' + NAMES[kind] + ' (' + PER_KIND * CASES + ' cases)', () => {
      const R = rng(5000 + kind);
      let finite = 0, neg = 0, total = 0;
      for (let n = 0; n < PER_KIND; n++) {
        const s = makeShape(kind, R, n);
        const id = load(s);
        for (let c = 0; c < CASES; c++) {
          const p = nearPoint(s, R, R() < 0.5 ? 0 : 3);
          const dt = closestOn(s, p[0], p[1], p[2]);
          const dk = ex.hk_t_closest(id, p[0], p[1], p[2]);
          const k = res();
          if (!(same(dk, dt) && same(k[8]!, C.dist) && same(k[9]!, C.nx) && same(k[10]!, C.ny) && same(k[11]!, C.nz))) {
            throw new Error('closest differs: ' + NAMES[kind] + ' ' + n + ' case ' + c + ' p=' + p + ' ts=' + [dt, C.dist, C.nx, C.ny, C.nz] + ' rs=' + [dk, k[8], k[9], k[10], k[11]]);
          }
          total++;
          if (Number.isFinite(dt)) finite++;
          if (dt < 0) neg++;
        }
      }
      expect(finite / total).toBeGreaterThan(0.5);
      if (kind !== K.mesh && kind !== K.heightfield) expect(neg).toBeGreaterThan(100);
    });
  }

  it('rayAabb, degenerate directions included (10,000 cases)', () => {
    const R = rng(777);
    const comp = (): number => {
      const k = R();
      return k < 0.12 ? 0 : k < 0.17 ? -0 : k < 0.22 ? 1e-13 : k < 0.27 ? -1e-13 : k < 0.3 ? 1e-12 : k < 0.33 ? -1e-12 : R() * 2 - 1;
    };
    let hits = 0;
    for (let c = 0; c < 10_000; c++) {
      const x0 = (R() * 2 - 1) * 5, y0 = (R() * 2 - 1) * 5, z0 = (R() * 2 - 1) * 5;
      let x1 = x0 + R() * 6, y1 = y0 + R() * 6, z1 = z0 + R() * 6;
      if (R() < 0.03) x1 = x0 - 1; // an empty box
      // Origins on a face or an edge now and then, so the comparisons at the boundary matter.
      const pick = (lo: number, hi: number): number => { const k = R(); return k < 0.1 ? lo : k < 0.2 ? hi : lo - 3 + R() * (hi - lo + 6); };
      const o = [pick(x0, x1), pick(y0, y1), pick(z0, z1)];
      const d = [comp(), comp(), comp()];
      const kt = R();
      const tmax = kt < 0.05 ? 0 : kt < 0.1 ? Infinity : R() * 20;
      const want = rayAabb(o[0]!, o[1]!, o[2]!, d[0]!, d[1]!, d[2]!, x0, y0, z0, x1, y1, z1, tmax);
      const got = ex.hk_t_ray_aabb(o[0]!, o[1]!, o[2]!, d[0]!, d[1]!, d[2]!, x0, y0, z0, x1, y1, z1, tmax) === 1;
      if (want !== got) throw new Error('rayAabb differs at case ' + c + ': o=' + o + ' d=' + d + ' box=' + [x0, y0, z0, x1, y1, z1] + ' tmax=' + tmax);
      if (want) hits++;
    }
    expect(hits).toBeGreaterThan(1000);
  });
});
